(ev.verified === false ? "" : '<span class="badge badge--verify" title="' + t("vf.tip", "소속사 소솝이 직접 확인한 정보입니다") + '">' + t("vf.badge", "소솝 확인") + "</span> ") +
"<h3>" + esc(tr(ev, "title")) + '</h3><p class="where">' + esc(tr(ev, "place")) + (ev.note ? " · " + esc(ev.note) : "") + "</p></div>" +
eventCta(ev);
